    if (row.occupancy) parts.push('房型线索：' + row.occupancy);
    if (row.bedType) parts.push('床型线索：' + row.bedType);
    if (row.bathroom) parts.push('卫浴线索：' + row.bathroom);
    if (!parts.length) parts.push('当前记录未提供可核验的校区、楼栋、房型、床型或卫浴细节');
    parts.push('以上为已有公开记录的结构化摘要；未列明的配置不作推断，当前分配与具体楼栋待核实。');
    return parts.join('；');
